parameters.content:
{
  "id": "83a68d14-56a8-410c-ac69-1868eae3489e",
  "version": "1.8",
  "name": "ExpenseApproval",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "Manual trigger"
      },
      "inputs": {
        "entryPointId": "377ad951-951d-4a92-b40b-c4c05e59f807",
        "isDefaultEntryPoint": true
      }
    },
    {
      "id": "buildForm",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Prepare Expense Details"
      },
      "inputs": {
        "script": "return {\n  submitterName: $vars.submitterName,\n  expenseDescription: $vars.expenseDescription,\n  amount: $vars.amount,\n  category: $vars.category\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the node fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "managerApproval",
      "type": "uipath.human-in-the-loop.quick-form",
      "typeVersion": "1.0",
      "display": {
        "label": "Manager Approval"
      },
      "inputs": {
        "title": "Expense Report Approval Request",
        "priority": "Medium",
        "schema": {
          "schemaId": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
          "fields": [
            {
              "id": "submitterName",
              "label": "Submitted By",
              "type": "text",
              "direction": "input",
              "binding": "vars.buildForm.output.submitterName"
            },
            {
              "id": "expenseDescription",
              "label": "Expense Description",
              "type": "text",
              "direction": "input",
              "binding": "vars.buildForm.output.expenseDescription"
            },
            {
              "id": "amount",
              "label": "Amount",
              "type": "number",
              "direction": "input",
              "binding": "vars.buildForm.output.amount"
            },
            {
              "id": "category",
              "label": "Category",
              "type": "text",
              "direction": "input",
              "binding": "vars.buildForm.output.category"
            },
            {
              "id": "managerComments",
              "label": "Manager Comments",
              "type": "text",
              "direction": "output",
              "variable": "vars.managerComments"
            }
          ],
          "outcomes": [
            {
              "id": "approve",
              "name": "Approve",
              "type": "string",
              "isPrimary": true,
              "action": "Continue"
            },
            {
              "id": "reject",
              "name": "Reject",
              "type": "string",
              "isPrimary": false,
              "action": "Continue"
            }
          ]
        },
        "recipient": {
          "channels": ["Email", "ActionCenter"],
          "connections": {},
          "assignee": {
            "type": "group"
          }
        }
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Task result data",
          "source": "=result",
          "var": "output",
          "properties": {
            "managerComments": { "type": "string" },
            "Action": {
              "type": "string",
              "enum": ["Approve", "Reject"],
              "default": "Approve"
            }
          }
        },
        "status": {
          "type": "string",
          "description": "Task completion status",
          "source": "=result.Action",
          "var": "status",
          "enum": ["Approve", "Reject"],
          "default": "Approve"
        }
      }
    },
    {
      "id": "checkDecision",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {
        "label": "Approved?"
      },
      "inputs": {
        "expression": "$vars.managerApproval.output.Action === \"Approve\"",
        "trueLabel": "Approved",
        "falseLabel": "Rejected"
      }
    },
    {
      "id": "notifyApproved",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Notify Submitter — Approved"
      },
      "inputs": {
        "script": "return {\n  message: 'Your expense report for ' + $vars.expenseDescription + ' ($' + $vars.amount + ') has been APPROVED.',\n  comments: $vars.managerApproval.output.managerComments || ''\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the node fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "notifyRejected",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Notify Submitter — Rejected"
      },
      "inputs": {
        "script": "return {\n  message: 'Your expense report for ' + $vars.expenseDescription + ' ($' + $vars.amount + ') has been REJECTED.',\n  comments: $vars.managerApproval.output.managerComments || ''\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the node fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "endApproved",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "Done — Approved"
      },
      "inputs": {},
      "outputs": {
        "approvalStatus": { "source": "=js:\"approved\"" },
        "notificationMessage": { "source": "=js:$vars.notifyApproved.output.message" }
      }
    },
    {
      "id": "endRejected",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "Done — Rejected"
      },
      "inputs": {},
